//! Involute gears in the transverse plane: external teeth generated by a rack cutter (so the
//! root fillet is the true trochoid and undercut comes out as it would on a hobbing machine),
//! internal teeth, and racks.

use std::f64::consts::{PI, TAU};

use crate::geom::{Outline, Seg, V2, inv, inv_inv};

/// The basic rack: tooth proportions in multiples of the normal module.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BasicRack {
    /// Addendum coefficient ha* (1.0 full depth, 0.8 stub).
    pub addendum: f64,
    /// Dedendum coefficient hf* = ha* + c* (1.25 for ISO 53 profile A/B).
    pub dedendum: f64,
    /// Root (cutter tip) radius coefficient ρf* (0.38 for ISO 53 A).
    pub root_radius: f64,
}

impl Default for BasicRack {
    fn default() -> Self {
        Self { addendum: 1.0, dedendum: 1.25, root_radius: 0.38 }
    }
}

impl BasicRack {
    /// ISO 53 profiles, AGMA full depth and stub: (name, rack).
    pub const STANDARDS: &'static [(&'static str, BasicRack)] = &[
        ("iso53_a", BasicRack { addendum: 1.0, dedendum: 1.25, root_radius: 0.38 }),
        ("iso53_b", BasicRack { addendum: 1.0, dedendum: 1.25, root_radius: 0.3 }),
        ("iso53_c", BasicRack { addendum: 1.0, dedendum: 1.25, root_radius: 0.25 }),
        ("iso53_d", BasicRack { addendum: 1.0, dedendum: 1.4, root_radius: 0.39 }),
        ("agma_full_depth", BasicRack { addendum: 1.0, dedendum: 1.25, root_radius: 0.3 }),
        ("stub", BasicRack { addendum: 0.8, dedendum: 1.0, root_radius: 0.3 }),
    ];
    pub fn standard(name: &str) -> Option<BasicRack> {
        Self::STANDARDS.iter().find(|(n, _)| *n == name).map(|(_, r)| *r)
    }
}

/// An involute gear's tooth data in the transverse plane.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Involute {
    /// Tooth count (positive).
    pub teeth: u32,
    /// Normal module mn (mm).
    pub module: f64,
    /// Normal pressure angle αn (radians).
    pub pressure_angle: f64,
    /// Helix angle β at the pitch circle (radians, 0 for spur; the sign is the hand).
    pub helix: f64,
    /// Profile shift coefficient x (shift = x·mn, positive away from the centre).
    pub shift: f64,
    pub rack: BasicRack,
    /// Circular backlash at the pitch circle (mm): the tooth is thinner by this much.
    pub backlash: f64,
    /// Tip shortening (mm off the tip radius), for example to keep tip clearance after shifting.
    pub tip_shortening: f64,
    /// A non-integer tooth count used for the geometry instead of `teeth` (a bevel gear's
    /// virtual spur gear); 0 for none.
    pub virtual_teeth: f64,
}

impl Default for Involute {
    fn default() -> Self {
        Self {
            teeth: 20,
            module: 2.0,
            pressure_angle: 20f64.to_radians(),
            helix: 0.0,
            shift: 0.0,
            rack: BasicRack::default(),
            backlash: 0.0,
            tip_shortening: 0.0,
            virtual_teeth: 0.0,
        }
    }
}

impl Involute {
    pub fn z(&self) -> f64 {
        if self.virtual_teeth > 0.0 { self.virtual_teeth } else { f64::from(self.teeth) }
    }
    /// Transverse module mt = mn / cos β.
    pub fn mt(&self) -> f64 {
        self.module / self.helix.cos()
    }
    /// Transverse pressure angle αt.
    pub fn alpha_t(&self) -> f64 {
        (self.pressure_angle.tan() / self.helix.cos()).atan()
    }
    /// Pitch (reference) radius.
    pub fn r(&self) -> f64 {
        self.mt() * self.z() / 2.0
    }
    /// Base radius.
    pub fn rb(&self) -> f64 {
        self.r() * self.alpha_t().cos()
    }
    /// External tip radius.
    pub fn ra(&self) -> f64 {
        self.r() + (self.rack.addendum + self.shift) * self.module - self.tip_shortening
    }
    /// External root radius.
    pub fn rf(&self) -> f64 {
        self.r() - (self.rack.dedendum - self.shift) * self.module
    }
    /// Transverse tooth thickness on the pitch circle (arc length).
    pub fn thickness(&self) -> f64 {
        PI * self.mt() / 2.0 + 2.0 * self.shift * self.module * self.alpha_t().tan() - self.backlash
    }
    /// Half the tooth's angular thickness at radius `rr` (on the involute; radians).
    pub fn half_angle_at(&self, rr: f64) -> f64 {
        let r = self.r();
        let rb = self.rb();
        let at = self.alpha_t();
        let ar = (rb / rr.max(rb)).clamp(-1.0, 1.0).acos();
        self.thickness() / (2.0 * r) + inv(at) - inv(ar)
    }
    /// The tooth's transverse thickness (arc) at radius `rr`.
    pub fn thickness_at(&self, rr: f64) -> f64 {
        2.0 * rr * self.half_angle_at(rr)
    }
    /// Smallest tooth count without undercut for this rack and shift.
    pub fn min_teeth_no_undercut(&self) -> f64 {
        2.0 * (self.rack.addendum - self.shift) * self.helix.cos() / self.alpha_t().sin().powi(2)
    }
    /// The radius below which the involute is cut away (undercut), or None.
    pub fn undercut(&self) -> bool {
        // The rack's straight flank ends at ha*·mn below the pitch line (shifted); undercut when
        // that point lies past the interference point on the line of action.
        let reach = (self.rack.addendum - self.shift) * self.module;
        reach > self.r() * self.alpha_t().sin().powi(2) + 1e-9
    }
    /// The tip radius at which the tooth becomes pointed.
    pub fn pointed_radius(&self) -> f64 {
        let v = self.thickness() / (2.0 * self.r()) + inv(self.alpha_t());
        self.rb() / inv_inv(v).cos()
    }
    /// The base pitch (transverse).
    pub fn base_pitch(&self) -> f64 {
        PI * self.mt() * self.alpha_t().cos()
    }
    /// Span measurement over k teeth (Wildhaber) with the k that touches near the pitch circle.
    pub fn span(&self) -> (u32, f64) {
        let an = self.pressure_angle;
        let at = self.alpha_t();
        let bb = (self.helix.sin() * an.cos()).asin();
        let z = self.z();
        // Virtual tooth count for helical gears.
        let k = ((z * at.tan() / bb.cos().powi(2) - z * inv(at) - 2.0 * self.shift * an.tan()) / PI + 0.5).round().max(1.0);
        let w = self.module * an.cos() * (PI * (k - 0.5) + z * inv(at)) + 2.0 * self.shift * self.module * an.sin() - self.backlash * an.cos() * self.helix.cos();
        (k as u32, w)
    }
    /// Measurement over two pins (balls for helical) of diameter `dp`; returns (M, pin diameter).
    pub fn over_pins(&self, dp: Option<f64>) -> (f64, f64) {
        let dp = dp.unwrap_or(1.728 * self.module);
        let at = self.alpha_t();
        let z = self.z();
        // Involute angle where the pin centre lies (ISO 21771, transverse).
        let v = self.thickness() / (2.0 * self.r()) + inv(at) + dp / (self.module * z * self.pressure_angle.cos()) - PI / z;
        let am = inv_inv(v);
        let rm = self.rb() / am.cos();
        let m = if self.teeth % 2 == 0 { 2.0 * rm + dp } else { 2.0 * rm * (PI / (2.0 * z)).cos() + dp };
        (m, dp)
    }
}

/// A rack cutter point and its outward normal (pointing from the cutter into the gear).
struct CutterPt {
    u: f64,
    v: f64,
    nu: f64,
    nv: f64,
}

/// The candidate curves the cutter generates for the right side of the tooth space centred on
/// +y: tip flat (root), fillet (trochoid) and flank (involute), each as gear points.
fn generated(g: &Involute) -> [Vec<V2>; 3] {
    let mn = g.module;
    let at = g.alpha_t();
    let r = g.r();
    let pt = PI * g.mt();
    let hc = g.rack.dedendum * mn;
    let datum = r + g.shift * mn;
    // Fillet: tangent to the tip line and the flank; no bigger than the tip allows.
    let u_tip_corner = pt / 4.0 - hc * at.tan();
    // Largest radius whose centre still sits right of the tooth middle (full round tip).
    let rho_max = (u_tip_corner.max(0.0)) / (1.0 / at.cos() - at.tan()).max(1e-9);
    let rho = (g.rack.root_radius * mn).min(rho_max * 0.999).max(1e-7);
    let vc = -hc + rho;
    let uc = pt / 4.0 + vc * at.tan() - rho / at.cos();
    let n_flank = (at.cos(), -at.sin());

    let mut tip = Vec::new();
    let steps = 8;
    for i in 0..=steps {
        tip.push(CutterPt { u: uc.max(0.0) * i as f64 / steps as f64, v: -hc, nu: 0.0, nv: -1.0 });
    }
    let mut fillet = Vec::new();
    // From straight down (−π/2) to the flank normal.
    let a0 = -PI / 2.0;
    let a1 = n_flank.1.atan2(n_flank.0);
    let steps = 60;
    for i in 0..=steps {
        let a = a0 + (a1 - a0) * i as f64 / steps as f64;
        fillet.push(CutterPt { u: uc + rho * a.cos(), v: vc + rho * a.sin(), nu: a.cos(), nv: a.sin() });
    }
    let mut flank = Vec::new();
    let (fu, fv) = (uc + rho * n_flank.0, vc + rho * n_flank.1);
    let v_top = (g.rack.addendum + g.rack.dedendum) * mn;
    let steps = 120;
    for i in 0..=steps {
        let v = fv + (v_top - fv) * i as f64 / steps as f64;
        let u = fu + (v - fv) * at.tan();
        flank.push(CutterPt { u, v, nu: n_flank.0, nv: n_flank.1 });
    }
    let map = |c: &CutterPt| -> V2 {
        let y = datum + c.v;
        // The normal through the pitch point (0, r): the rack's displacement s.
        let s = if c.nv.abs() > 1e-12 { (y - r) * c.nu / c.nv - c.u } else { -c.u };
        let x = c.u + s;
        V2::new(x, y).rot(s / r)
    };
    [tip.iter().map(map).collect(), fillet.iter().map(map).collect(), flank.iter().map(map).collect()]
}

/// The angle from +y towards +x (clockwise), for the tooth space centred on +y.
fn psi(p: V2) -> f64 {
    p.x.atan2(p.y)
}

/// The space's half angle at radius `rr`: the largest angle any generated curve reaches there,
/// and which curve (0 tip, 1 fillet, 2 flank).
fn space_half(curves: &[Vec<V2>; 3], rr: f64) -> Option<(f64, usize)> {
    let mut best: Option<(f64, usize)> = None;
    for (k, c) in curves.iter().enumerate() {
        for w in c.windows(2) {
            let (ra, rb) = (w[0].len(), w[1].len());
            if (ra - rr) * (rb - rr) <= 0.0 && (ra - rb).abs() > 1e-12 {
                let t = (rr - ra) / (rb - ra);
                let a = psi(w[0]) + (psi(w[1]) - psi(w[0])) * t;
                if best.is_none_or(|(b, _)| a > b) {
                    best = Some((a, k));
                }
            }
        }
    }
    best
}

/// A generated external tooth: its flank (from the root up) as the tooth's half angle against
/// radius, split where the fillet meets the involute.
#[derive(Clone, Debug)]
pub struct ToothFlank {
    /// Root radius, tip radius actually used (lowered when the tooth would be pointed).
    pub rf: f64,
    pub ra: f64,
    /// Half angles of the tooth at the root and the tip.
    pub root_half: f64,
    pub tip_half: f64,
    /// (radius, half angle) from the root to where the fillet ends.
    pub fillet: Vec<(f64, f64)>,
    /// (radius, half angle) from there to the tip.
    pub flank: Vec<(f64, f64)>,
    /// The flank is cut away near its base (undercut).
    pub undercut: bool,
    /// The tooth came to a point before its tip radius.
    pub pointed: bool,
}

/// Generates the flank of an external involute tooth with its trochoidal root fillet.
pub fn external_flank(g: &Involute) -> ToothFlank {
    let curves = generated(g);
    let z = g.z();
    let r = g.r();
    let rf = g.rf();
    let backlash_turn = g.backlash / (2.0 * r);
    let half = |rr: f64| -> Option<(f64, usize)> { space_half(&curves, rr).map(|(s, k)| (PI / z - s - backlash_turn, k)) };
    // The root: the tip flat's last point.
    let root_half = PI / z - psi(*curves[0].last().unwrap_or(&V2::new(0.0, rf))) - backlash_turn;
    // Tip: lowered to where the tooth keeps a sliver of land if it would be pointed.
    let mut ra = g.ra();
    let mut pointed = false;
    let land = 0.02 * g.module;
    if let Some((h, _)) = half(ra)
        && h * ra < land / 2.0
    {
        pointed = true;
        let (mut lo, mut hi) = (rf, ra);
        for _ in 0..60 {
            let mid = (lo + hi) / 2.0;
            match half(mid) {
                Some((h, _)) if h * mid > land / 2.0 => lo = mid,
                _ => hi = mid,
            }
        }
        ra = lo;
    }
    // Where the fillet hands over to the flank (the last radius won by a non-flank curve).
    let probe = 400;
    let mut handover = rf;
    let mut seen_flank = false;
    for i in 1..=probe {
        let rr = rf + (ra - rf) * i as f64 / probe as f64;
        if let Some((_, k)) = half(rr) {
            if k == 2 {
                if !seen_flank {
                    handover = rr;
                }
                seen_flank = true;
            } else if !seen_flank {
                handover = rr;
            }
        }
    }
    if !seen_flank {
        handover = ra;
    }
    let undercut = g.undercut();
    // Samples: denser towards the root, where the fillet bends most, but never so close that
    // the spline through them kinks.
    let n = if g.z() > 80.0 { 7 } else if g.z() > 40.0 { 9 } else { 11 };
    let mut fillet = Vec::new();
    for i in 0..=n {
        let t = i as f64 / n as f64;
        let rr = rf + (handover - rf) * t.powf(1.4);
        let rr = if i == 0 { rf + (handover - rf) * 1e-6 } else { rr };
        if let Some((h, _)) = half(rr) {
            fillet.push((rr, h));
        }
    }
    let mut flank = Vec::new();
    for i in 0..=n {
        let t = i as f64 / n as f64;
        let rr = handover + (ra - handover) * t;
        if let Some((h, _)) = half(rr) {
            flank.push((rr, h));
        }
    }
    if let (Some(a), Some(b)) = (fillet.last().copied(), flank.first().copied())
        && (a.0 - b.0).abs() < 1e-9
    {
        flank[0] = a;
    }
    let tip_half = flank.last().map(|p| p.1).unwrap_or(root_half);
    ToothFlank { rf, ra, root_half: root_half.max(0.0), tip_half, fillet, flank, undercut, pointed }
}

/// Teeth placed round the centre, tooth 0 centred at `phase` (radians from +x).
pub fn external_outline(g: &Involute, phase: f64) -> (Outline, ToothFlank) {
    let f = external_flank(g);
    (teeth_outline(&f, g.teeth, phase), f)
}

/// The closed outline of `n` teeth with flank `f`, counter-clockwise.
pub fn teeth_outline(f: &ToothFlank, n: u32, phase: f64) -> Outline {
    let pitch = TAU / f64::from(n);
    let mut segs = Vec::new();
    // One tooth centred on +x: up its clockwise side (negative angles), across the tip, down the
    // other side, then the root arc to the next tooth.
    let side = |pts: &[(f64, f64)], sign: f64| -> Vec<V2> { pts.iter().map(|(rr, h)| V2::polar(*rr, sign * h)).collect() };
    let lower_fillet = side(&f.fillet, -1.0);
    let lower_flank = side(&f.flank, -1.0);
    let upper_flank: Vec<V2> = side(&f.flank, 1.0).into_iter().rev().collect();
    let upper_fillet: Vec<V2> = side(&f.fillet, 1.0).into_iter().rev().collect();
    let root_gap = pitch - 2.0 * f.root_half;
    for k in 0..n {
        let a = phase + pitch * f64::from(k);
        let rot = |p: &Vec<V2>| -> Vec<V2> { p.iter().map(|q| q.rot(a)).collect() };
        let start = V2::polar(f.rf, a - f.root_half);
        let mut lf = rot(&lower_fillet);
        if lf.len() >= 2 {
            lf[0] = start;
            segs.push(Seg::Spline(lf));
        }
        if lower_flank.len() >= 2 {
            segs.push(Seg::Spline(rot(&lower_flank)));
        }
        let (ta, tb) = (V2::polar(f.ra, a - f.tip_half), V2::polar(f.ra, a + f.tip_half));
        if f.tip_half > 1e-9 {
            segs.push(Seg::Arc { c: V2::ZERO, a: ta, b: tb, ccw: true });
        }
        if upper_flank.len() >= 2 {
            segs.push(Seg::Spline(rot(&upper_flank)));
        }
        let mut uf = rot(&upper_fillet);
        let end = V2::polar(f.rf, a + f.root_half);
        if uf.len() >= 2 {
            let l = uf.len() - 1;
            uf[l] = end;
            segs.push(Seg::Spline(uf));
        }
        if root_gap > 1e-6 {
            segs.push(Seg::Arc { c: V2::ZERO, a: end, b: V2::polar(f.rf, a + pitch - f.root_half), ccw: true });
        }
    }
    join_ends(&mut segs);
    Outline { segs }
}

/// Snap each segment's start onto the previous one's end (sampling leaves tiny gaps).
pub(crate) fn join_ends(segs: &mut [Seg]) {
    let n = segs.len();
    for i in 0..n {
        let prev_end = segs[(i + n - 1) % n].end();
        match &mut segs[i] {
            Seg::Line(a, _) => *a = prev_end,
            Seg::Arc { a, .. } => *a = prev_end,
            Seg::Spline(p) => p[0] = prev_end,
            Seg::Circle(..) => {}
        }
    }
}

/// An internal (ring) gear's teeth: the tooth spaces are involute "teeth" pointing outwards.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Internal {
    pub gear: Involute,
}

impl Internal {
    /// Internal tip radius (the teeth's inner ends).
    pub fn r_tip(&self) -> f64 {
        let g = &self.gear;
        g.r() - (g.rack.addendum - g.shift) * g.module + g.tip_shortening
    }
    /// Internal root radius (outer).
    pub fn r_root(&self) -> f64 {
        let g = &self.gear;
        g.r() + (g.rack.dedendum + g.shift) * g.module
    }
    /// Space width on the pitch circle (arc).
    pub fn space(&self) -> f64 {
        let g = &self.gear;
        PI * g.mt() / 2.0 - 2.0 * g.shift * g.module * g.alpha_t().tan() + g.backlash
    }
    /// The space's half angle at radius `rr` (the involute, radial below the base circle).
    pub fn space_half_at(&self, rr: f64) -> f64 {
        let g = &self.gear;
        let rb = g.rb();
        let ar = (rb / rr.max(rb)).acos();
        self.space() / (2.0 * g.r()) + inv(g.alpha_t()) - inv(ar)
    }
    /// The toothed boundary, counter-clockwise; tooth 0 (material) centred at `phase`.
    pub fn outline(&self, phase: f64, root_fillet: f64) -> Outline {
        let g = &self.gear;
        let (r0, r1) = (self.r_tip(), self.r_root());
        let n = 16;
        let mut pts = Vec::new();
        for i in 0..=n {
            let t = i as f64 / n as f64;
            let rr = r0 + (r1 - r0) * t;
            pts.push((rr, self.space_half_at(rr).max(0.0)));
        }
        let _ = root_fillet;
        // The "tooth" of the virtual external gear is the internal space.
        let f = ToothFlank {
            rf: r0,
            ra: r1,
            root_half: pts[0].1,
            tip_half: pts[n].1,
            fillet: vec![pts[0], pts[1]],
            flank: pts[1..].to_vec(),
            undercut: false,
            pointed: pts[n].1 <= 0.0,
        };
        teeth_outline(&f, g.teeth, phase + PI / g.z())
    }
}

/// A straight-toothed rack's outline in the plane: teeth along +x, pitch line at y = 0, teeth
/// pointing +y, from x = 0 for `count` teeth, body down to y = −`depth_below`.
pub fn rack_outline(g: &Involute, count: u32, depth_below: f64) -> Outline {
    let p = PI * g.mt();
    let at = g.alpha_t();
    let ha = (g.rack.addendum + g.shift) * g.module - g.tip_shortening;
    let hf = (g.rack.dedendum - g.shift) * g.module;
    // Tooth thickness on the pitch line.
    let s = p / 2.0 - g.backlash;
    let half_tip = s / 2.0 - ha * at.tan();
    let half_root = s / 2.0 + hf * at.tan();
    let mut pts = vec![V2::new(0.0, -depth_below)];
    let x_end = p * f64::from(count);
    pts.push(V2::new(x_end, -depth_below));
    let mut top = Vec::new();
    for k in 0..count {
        let c = p * (f64::from(k) + 0.5);
        top.push(V2::new(c - half_root.min(p / 2.0), -hf));
        top.push(V2::new(c - half_tip.max(0.0), ha));
        top.push(V2::new(c + half_tip.max(0.0), ha));
        top.push(V2::new(c + half_root.min(p / 2.0), -hf));
    }
    pts.push(V2::new(x_end, -hf));
    pts.extend(top.into_iter().rev());
    pts.push(V2::new(0.0, -hf));
    let mut segs = Vec::new();
    let mut clean: Vec<V2> = Vec::new();
    for q in pts {
        if clean.last().is_none_or(|l: &V2| l.dist(q) > 1e-9) {
            clean.push(q);
        }
    }
    for i in 0..clean.len() {
        segs.push(Seg::Line(clean[i], clean[(i + 1) % clean.len()]));
    }
    Outline { segs }
}

/// Contact ratio and geometry of two external (or external with internal) involute gears in mesh.
#[derive(Clone, Copy, Debug, PartialEq, Default)]
pub struct Mesh {
    /// Working transverse pressure angle (radians).
    pub working_pressure_angle: f64,
    /// Reference (no shift) and working centre distance.
    pub center_distance_ref: f64,
    pub center_distance: f64,
    /// Transverse, overlap and total contact ratios.
    pub contact_ratio: f64,
    pub overlap_ratio: f64,
    pub total_contact_ratio: f64,
    /// Tip clearances at the two roots (mm).
    pub clearance_1: f64,
    pub clearance_2: f64,
    pub ratio: f64,
}

/// Mesh of two external gears (same module, pressure angle and opposite helix), `face` wide.
pub fn mesh_external(g1: &Involute, g2: &Involute, face: f64) -> Mesh {
    let at = g1.alpha_t();
    let (z1, z2) = (g1.z(), g2.z());
    let inv_w = 2.0 * g1.pressure_angle.tan() * (g1.shift + g2.shift) / (z1 + z2) + inv(at);
    let aw_t = inv_inv(inv_w);
    let a0 = g1.r() + g2.r();
    let aw = a0 * at.cos() / aw_t.cos();
    let (ra1, ra2) = (g1.ra(), g2.ra());
    let (rb1, rb2) = (g1.rb(), g2.rb());
    let ea = ((ra1 * ra1 - rb1 * rb1).max(0.0).sqrt() + (ra2 * ra2 - rb2 * rb2).max(0.0).sqrt() - aw * aw_t.sin()) / g1.base_pitch();
    let eb = face * g1.helix.abs().sin() / (PI * g1.module);
    Mesh {
        working_pressure_angle: aw_t,
        center_distance_ref: a0,
        center_distance: aw,
        contact_ratio: ea,
        overlap_ratio: eb,
        total_contact_ratio: ea + eb,
        clearance_1: aw - ra2 - g1.rf(),
        clearance_2: aw - ra1 - g2.rf(),
        ratio: z2 / z1,
    }
}

/// Mesh of an external pinion inside an internal gear.
pub fn mesh_internal(pinion: &Involute, ring: &Internal, face: f64) -> Mesh {
    let at = pinion.alpha_t();
    let (z1, z2) = (pinion.z(), ring.gear.z());
    let inv_w = 2.0 * pinion.pressure_angle.tan() * (ring.gear.shift - pinion.shift) / (z2 - z1) + inv(at);
    let aw_t = inv_inv(inv_w);
    let a0 = ring.gear.r() - pinion.r();
    let aw = a0 * at.cos() / aw_t.cos();
    let (ra1, ra2) = (pinion.ra(), ring.r_tip());
    let (rb1, rb2) = (pinion.rb(), ring.gear.rb());
    let ea = ((ra1 * ra1 - rb1 * rb1).max(0.0).sqrt() - (ra2 * ra2 - rb2 * rb2).max(0.0).sqrt() + aw * aw_t.sin()) / pinion.base_pitch();
    let eb = face * pinion.helix.abs().sin() / (PI * pinion.module);
    Mesh {
        working_pressure_angle: aw_t,
        center_distance_ref: a0,
        center_distance: aw,
        contact_ratio: ea,
        overlap_ratio: eb,
        total_contact_ratio: ea + eb,
        clearance_1: ring.r_root() - aw - ra1,
        clearance_2: aw + ra2 - pinion.rf(),
        ratio: z2 / z1,
    }
}

/// The total profile shift (x1 + x2) that brings two external gears to centre distance `aw`.
pub fn shift_sum_for_center(g1: &Involute, g2: &Involute, aw: f64) -> Option<f64> {
    let at = g1.alpha_t();
    let a0 = g1.r() + g2.r();
    let c = a0 * at.cos() / aw;
    if !(-1.0..=1.0).contains(&c) {
        return None;
    }
    let aw_t = c.acos();
    Some((inv(aw_t) - inv(at)) * (g1.z() + g2.z()) / (2.0 * g1.pressure_angle.tan()))
}

/// How gear 2 must be turned to mesh with gear 1: gear 1 at the origin with tooth 0 at `phase1`,
/// gear 2's centre in direction `dir` from it. External mesh. Returns gear 2's tooth-0 angle.
pub fn mesh_phase(z1: u32, phase1: f64, z2: u32, dir: f64) -> f64 {
    let (z1, z2) = (f64::from(z1), f64::from(z2));
    dir + PI + PI / z2 - (z1 / z2) * (dir - phase1)
}
